import java.io.*;

public class Main {

    static class Account implements Serializable {
        private static final long serialVersionUID = 1L;
        String owner;
        transient String password;      // NOT written to the stream
        long amount;

        Account(String owner, String password, long amount) {
            this.owner = owner;
            this.password = password;
            this.amount = amount;
        }
    }

    /** No explicit serialVersionUID: the value is computed from the class structure. */
    static class NoUid implements Serializable {
        int a;
        String b;
    }

    public static void main(String[] args) throws Exception {
        Account acc = new Account("alice", "s3cret", 500);
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        try (ObjectOutputStream out = new ObjectOutputStream(bos)) {
            out.writeObject(acc);
        }
        byte[] blob = bos.toByteArray();
        System.out.println("serialized byte length                    : " + blob.length);
        System.out.println("stream header starts with magic AC ED     : "
                + (blob.length > 2 && (blob[0] & 0xff) == 0xAC && (blob[1] & 0xff) == 0xED));

        Account back;
        try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(blob))) {
            back = (Account) in.readObject();
        }
        System.out.println("owner survived round trip                 : " + "alice".equals(back.owner));
        System.out.println("amount survived round trip                : " + (back.amount == 500));
        System.out.println("transient password after read (null)      : " + (back.password == null));

        long uid = ObjectStreamClass.lookup(Account.class).getSerialVersionUID();
        System.out.println("explicit serialVersionUID == 1L            : " + (uid == 1L));

        long auto = ObjectStreamClass.lookup(NoUid.class).getSerialVersionUID();
        System.out.println("class without serialVersionUID gets a hash: " + (auto != 1L));
        System.out.println("(that hash changes whenever fields change -> InvalidClassException across versions)");
        System.out.println("deserialization does NOT call the constructor (password never re-initialized)");
    }
}
